  'termsPolicy.toc.services': 'وصف الخدمات',
  'termsPolicy.toc.eligibility': 'الأهلية',
  'termsPolicy.toc.userAccounts': 'حسابات المستخدمين',
  'termsPolicy.toc.acceptableUse': 'الاستخدام المقبول',
  'termsPolicy.toc.orderFulfillment': 'تنفيذ الطلبات',
